(() => {
 function create(c){
  const e=c.esc,B=window.TravelProposalBrand,F=window.TravelSalesFlow;
  let sending=false,pdfUrl='';
  const button=(text,action,id,primary=false)=>`<button type="button" class="${primary?'primary':'outline'}-button" data-action="${action}" data-id="${e(id)}">${text}</button>`;
  const brand=b=>B.normalize(b.brand||c.state.proposalBrand);
  const formatted=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.split('-').reverse().join('/'):new Date(value).toLocaleString('pt-BR');
  function decor(b){const br=brand(b);return `<section class="sales-personalization"><span class="panel-caption">APRESENTAÇÃO DA PROPOSTA</span><h3>Uma viagem com a sua assinatura</h3><p>Modelo editorial TravelPro. Personalize a marca da agência; as assinaturas TravelPro e Europlus permanecem no material.</p><div class="proposal-brand-editor"><div class="proposal-logo-preview">${br.logo?`<img src="${e(br.logo)}" alt="Logo da agência">`:`<strong>${e(c.state.agency)}</strong>`}</div><label class="form-field"><span>Logo da agência</span><input type="file" data-proposal-logo accept="image/*,.jfif,.svg,.avif,.ico"><small>Imagens de até 20 MB: PNG, JPG, WebP, SVG, GIF, BMP ou AVIF. Ajustamos tamanho e proporção e extraímos até duas cores.</small></label><input type="hidden" name="brandLogo" value="${e(br.logo)}"></div><div class="form-grid"><label class="form-field"><span>Cor principal</span><input name="brandPrimary" type="color" value="${br.primary}"></label><label class="form-field"><span>Cor de apoio</span><input name="brandSecondary" type="color" value="${br.secondary}"></label></div><p role="status" id="proposal-palette-status"></p><label class="form-field"><span>Estilo</span><select name="appearance"><option value="classic" ${b.appearance!=='warm'?'selected':''}>Editorial · assinatura clássica</option><option value="warm" ${b.appearance==='warm'?'selected':''}>Editorial · acolhedor</option></select></label><label class="form-field"><span>Selo / adesivo (opcional)</span><input name="badge" maxlength="60" value="${e(b.badge||'')}" placeholder="Pensada especialmente para você"></label><label class="form-field"><span>Mensagem para o cliente</span><textarea name="introduction" maxlength="6000" rows="3">${e(b.introduction||'')}</textarea></label><p>Validade da cotação: ${e(formatted(b.validUntil||b.valid))}</p><h3>Inclusões da cotação</h3><ul>${(b.inclusions||[]).map(v=>'<li>'+e(v)+'</li>').join('')}</ul>${button('Visualizar apresentação','sales-preview',b.id)}${button('Baixar PDF','sales-download',b.id)}<section class="proposal-send-section"><span class="panel-caption">ENVIO AO CLIENTE</span><h3>Enviar proposta</h3><p>Mensagem personalizada e PDF pelo WhatsApp Business da agência. Confira o destinatário antes de enviar.</p>${button('Enviar proposta pelo WhatsApp','sales-send',b.id,true)}${button('Registrar resposta ou envio externo','sales-decision',b.id)}${b.delivery?'<p>PDF aceito pelo WhatsApp. Entrega e leitura ainda não confirmadas.</p>':''}</section></section>`;}
  function presentation(b){const br=brand(b),name=c.client(b.client).name;return `<article class="proposal-editorial ${b.appearance==='warm'?'proposal-warm':''}" style="--proposal-primary:${br.primary};--proposal-secondary:${br.secondary};--proposal-ink:${B.ink(br.primary)}"><header>${br.logo?`<img class="proposal-agency-logo" src="${e(br.logo)}" alt="${e(c.state.agency)}">`:`<strong>${e(c.state.agency)}</strong>`}<span>PROPOSTA DE VIAGEM</span></header><section class="proposal-cover"><span class="proposal-kicker">SUA PRÓXIMA VIAGEM</span><h1>${e(b.destination)}</h1><p>Preparada para ${e(name)}</p>${b.badge?'<span class="proposal-seal">'+e(b.badge)+'</span>':''}<div class="proposal-arc" aria-hidden="true"></div></section><div class="proposal-content"><div class="proposal-facts"><div><small>PERÍODO</small><strong>${e(formatted(b.start))} — ${e(formatted(b.end))}</strong></div><div><small>VIAJANTES</small><strong>${b.travelers} pessoas</strong></div></div><p class="proposal-intro">${e(b.introduction||'Uma viagem pensada para você, com os serviços e o cuidado da nossa agência.')}</p><span class="proposal-kicker">01 / A EXPERIÊNCIA</span><h2>Sua viagem, em detalhes</h2><ul class="proposal-inclusions">${(b.inclusions||[]).map(v=>'<li>'+e(v)+'</li>').join('')}</ul><section class="proposal-investment"><span class="proposal-kicker">02 / INVESTIMENTO</span>${b.items.map(i=>`<div class="proposal-price-row"><span>${e(i.name)} · ${i.qty} ×</span><strong>${c.money(i.unit)}</strong></div>`).join('')}<div class="proposal-total"><small>TOTAL DO GRUPO</small><strong>${c.money(c.total(b).total)}</strong><span>${c.money(c.total(b).total/b.travelers)} por viajante${b.discount?' · desconto de '+c.money(b.discount)+' incluído':''}</span></div></section><span class="proposal-kicker">03 / ANTES DE EMBARCAR</span><h2>Condições e próximos passos</h2><p><strong>Validade: ${e(formatted(b.validUntil||b.valid))}</strong></p><p class="sales-pre">${e(b.notes)}</p><p>Gostou da proposta? Responda à sua agência para aprovar ou solicitar ajustes.</p><p class="proposal-fine">A aprovação não confirma reserva, pagamento ou emissão. Valores e disponibilidade devem ser reconfirmados com a operadora.</p></div><footer><div><small>TECNOLOGIA</small><img src="assets/travelpro-assinatura-transparente.png" alt="TravelPro"></div><div><small>OPERADORA</small><img src="assets/europlus-logo.png" alt="Europlus"></div></footer></article>`;}
  function refinedPresentation(b){
   const d=b.details?F.normalizeDetails(b.details):{services:[],paymentTerms:[]},sum=c.total(b).total,p=d.price;
   const service=(label,title,lines)=>`<section class="proposal-service"><span class="proposal-kicker">${e(label)}</span><h3>${e(title)}</h3><ul>${lines.map(v=>'<li>'+e(v)+'</li>').join('')}</ul></section>`;
   const view=document.createElement('template');view.innerHTML=presentation(b);const root=view.content;
   const br=brand(b),theme=B.theme(br),article=root.querySelector('article');for(const [key,value]of Object.entries(theme))article.style.setProperty('--proposal-'+key,value);article.style.setProperty('--proposal-accent',theme.from);if(br.logo)root.querySelector('header').classList.add('has-agency-logo');
   root.querySelector('.proposal-arc')?.remove();
   root.querySelector('.proposal-inclusions').outerHTML=`<div class="proposal-services">${d.services.length?d.services.map(s=>service(({stay:'Hospedagem',flight:'Aéreo',transfer:'Traslado',other:'Serviço'})[s.kind],s.title,s.lines)).join(''):service('Serviços inclusos','O que faz parte da sua viagem',b.inclusions||[])}</div>`;
   const investment=root.querySelector('.proposal-investment');
   if(p&&Math.round((p.products+p.fees+p.taxes)*100)===Math.round((sum+b.discount)*100)){
    investment.querySelectorAll('.proposal-price-row').forEach(n=>n.remove());
    investment.querySelector('.proposal-total').insertAdjacentHTML('beforebegin',[['Produtos',p.products],['Taxas',p.fees],['Impostos',p.taxes]].map(([label,value])=>`<div class="proposal-price-row"><span>${label}</span><strong>${c.money(value)}</strong></div>`).join(''));
    investment.querySelector('.proposal-total small').textContent='TOTAL DO GRUPO · COM TAXAS';
   }
   if(d.paymentTerms.length)investment.insertAdjacentHTML('afterend',service('Pagamento','Escolha como seguir',d.paymentTerms));
   const validity=root.querySelector('.proposal-content>p>strong');
   if(!b.validUntil&&!b.valid)validity.textContent='Validade: não informada; confirmar com a operadora';
   if(b.sourceReference)validity.parentElement.insertAdjacentHTML('beforebegin',`<p>Referência da cotação: ${e(b.sourceReference)}</p>`);
   return view.innerHTML;
  }
  function pdfBlob(data){return new Blob([Uint8Array.from(atob(data.base64),v=>v.charCodeAt(0))],{type:'application/pdf'});}
  function download(data){const url=URL.createObjectURL(pdfBlob(data)),a=document.createElement('a');a.href=url;a.download=data.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  async function action(action,id){
    if(!['sales-preview','sales-download','sales-send'].includes(action))return false;
    if(c.editorOpen()&&!c.saveBudget())return true;
    const b=c.state.budgets.find(b=>b.id===id);if(!b)throw Error('Proposta não encontrada.');
    if(action==='sales-preview'){c.dialog('Apresentação para o cliente',refinedPresentation(b)+`<div class="sales-links">${button('Baixar PDF','sales-download',id)}${button('Enviar proposta','sales-send',id,true)}</div>`,'PROPOSTA');return true;}
    await c.flush();c.toast('Preparando o PDF…');const data=await c.request('/proposals/preview',{method:'POST',body:{id}});
    if(action==='sales-download'){download(data);return true;}
    if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(pdfBlob(data));
    c.dialog('Enviar proposta',`<form data-form="sales-send"><input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="fingerprint" value="${e(data.fingerprint)}"><div class="proposal-recipient"><small>DESTINATÁRIO</small><strong>${e(data.recipient)}</strong><span>${e(data.phone||'Telefone não cadastrado')}</span><small>Remetente: número da agência configurado em Conexões</small></div><p><a class="outline-button" href="${pdfUrl}" target="_blank" rel="noopener">Conferir PDF · ${e(data.filename)}</a></p><label class="form-field"><span>Mensagem personalizada</span><textarea name="message" rows="9" maxlength="1000" required>${e(data.message)}</textarea></label><div class="proposal-file">PDF anexado · ${e(data.filename)}</div>${!data.ready?`<p class="proposal-send-warning">${e(data.reason)}</p><a href="integracoes.html">Abrir Conexões</a>`:'<p>A mensagem e o PDF serão enviados ao contato acima. O WhatsApp confirmará o aceite; entrega e leitura podem ocorrer depois.</p>'}<p id="proposal-send-result" role="status"></p><div class="dialog-actions"><button class="primary-button" type="submit" ${data.ready?'':'disabled'}>Enviar mensagem e PDF</button></div></form>`,'WHATSAPP DA AGÊNCIA');return true;
  }
  async function submit(name,d){if(name!=='sales-send')return false;if(sending)return true;sending=true;const form=document.querySelector('[data-form="sales-send"]'),send=form?.querySelector('button[type="submit"]');if(send)send.disabled=true;
    try{const result=await c.request('/proposals/send',{method:'POST',body:{id:d.id,fingerprint:d.fingerprint,message:d.message}});if(result.status==='sent'){c.close();await c.refresh();c.toast('PDF aceito pelo WhatsApp. Aguardando resposta do cliente.');}else{const p=form?.querySelector('#proposal-send-result');if(p)p.textContent=result.status==='sent_sync_pending'?'PDF enviado. O histórico precisa ser conciliado; não repita o envio.':'Existe um envio em andamento ou sem confirmação. Confira a conversa antes de tentar novamente.';}}
    catch(error){const p=form?.querySelector('#proposal-send-result');if(p)p.textContent=error.message;else c.toast(error.message);}finally{sending=false;}return true;
  }
  document.addEventListener('change',async event=>{
    if(!event.target.matches('[data-proposal-logo]'))return;
    const file=event.target.files?.[0],form=event.target.closest('form');if(!file||!form)return;
    const status=form.querySelector('#proposal-palette-status');
    try{status.textContent='Adaptando o logo e extraindo as cores…';
      const {colors,logo}=await B.prepareLogo(file);
      form.elements.brandLogo.value=logo;form.elements.brandPrimary.value=colors[0];form.elements.brandSecondary.value=colors[1]||colors[0];form.querySelector('.proposal-logo-preview').innerHTML=`<img src="${logo}" alt="Logo da agência">`;
      status.textContent=colors.length===2?'Duas cores identificadas. Ajuste se desejar.':'Uma cor predominante identificada. Você pode escolher uma segunda cor.';
      if(c.saveBudget()){await c.flush();c.toast('Logo e cores salvos na proposta.');}
    }catch(error){status.textContent=error.message;}finally{event.target.value='';}
  });
  return {decor,presentation:refinedPresentation,action,submit};
 }
 window.TravelProposalUI={create};
})();
